package com.verzik_camera_fix;

import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import net.runelite.client.callback.RenderCallback;

import javax.inject.Inject;

public class ObjectHider implements RenderCallback {

    private final int[] verzikWallIds = {32700, 32699, 32701};

    @Inject
    ObjectHider() {
    }

    @Override
    public boolean drawObject(Scene scene, TileObject object) {
        for (int id : verzikWallIds) {
            if (object.getId() == id && object.getY() < 7000) {
                return false;
            }
        }
        return RenderCallback.super.drawObject(scene, object);
    }

}

package com.verzik_camera_fix;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import javax.inject.Inject;

@Slf4j
@PluginDescriptor(
        name = "Verzik camera fix",
        description = "Prevents the game camera from turning when entering Verzik's room, and hides the south wall.",
        tags = {"camera", "tob", "wall", "verzik"}
)
public class VerzikCameraFix extends Plugin {

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private RenderCallbackManager renderCallbackManager;

    @Inject
    private ObjectHider hider;

    private final int verzikCameraScriptId = 143;

    @Override
    protected void startUp() throws Exception {
        renderCallbackManager.register(hider);
        reloadMap();
    }

    @Override
    protected void shutDown() throws Exception {
        renderCallbackManager.unregister(hider);
        reloadMap();
    }

    // Forces a map load to show/hide objects
    private void reloadMap() {
        clientThread.invoke(() ->
        {
            if (client.getGameState() == GameState.LOGGED_IN) {
                client.setGameState(GameState.LOADING);
            }
        });
    }

    @Subscribe
    public void onScriptPreFired(ScriptPreFired event) {
        if (event.getScriptId() == verzikCameraScriptId) {
            event.getScriptEvent().getArguments()[2] = client.getCameraYaw();
        }
    }

}

package com.verzik_camera_fix;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class VerzikCameraFixTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(VerzikCameraFix.class);
		RuneLite.main(args);
	}
}
